package sandbox

import (
	"testing"
)

func Reverse(s string) string {
	runes := []rune(s)
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	return string(runes)
}

func TestReverse(t *testing.T) {
	tests := []struct {
		name     string
		input    string
		expected string
	}{
		{
			name:     "empty string",
			input:    "",
			expected: "",
		},
		{
			name:     "single character",
			input:    "a",
			expected: "a",
		},
		{
			name:     "english words",
			input:    "hello",
			expected: "olleh",
		},
		{
			name:     "mixed case",
			input:    "Hello World",
			expected: "dlroW olleH",
		},
		{
			name:     "unicode characters",
			input:    "你好世界",
			expected: "界世好你",
		},
		{
			name:     "emoji",
			input:    "😀😃😄",
			expected: "😄😃😀",
		},
		{
			name:     "mixed unicode and ascii",
			input:    "Hello 世界",
			expected: "界世 olleH",
		},
		{
			name:     "with spaces and punctuation",
			input:    "A man, a plan, a canal: Panama",
			expected: "amanaP :lanac a ,nalp a ,nam A",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := Reverse(tt.input)
			if result != tt.expected {
				t.Errorf("Reverse(%q) = %q, want %q", tt.input, result, tt.expected)
			}
		})
	}
}

package sandbox

import (
	"strings"
	"testing"
)

func WordCount(s string) map[string]int {
	words := strings.Fields(s)
	counts := make(map[string]int)
	for _, word := range words {
		counts[word]++
	}
	return counts
}

func TestWordCount(t *testing.T) {
	tests := []struct {
		input    string
		expected map[string]int
	}{
		{
			input:    "hello world hello",
			expected: map[string]int{"hello": 2, "world": 1},
		},
		{
			input:    "",
			expected: map[string]int{},
		},
		{
			input:    "   ",
			expected: map[string]int{},
		},
		{
			input:    "a b c d e",
			expected: map[string]int{"a": 1, "b": 1, "c": 1, "d": 1, "e": 1},
		},
		{
			input:    "  hello   world  hello  ",
			expected: map[string]int{"hello": 2, "world": 1},
		},
		{
			input:    "foo bar foo baz bar foo",
			expected: map[string]int{"foo": 3, "bar": 2, "baz": 1},
		},
	}

	for _, test := range tests {
		result := WordCount(test.input)
		if len(result) != len(test.expected) {
			t.Errorf("WordCount(%q) expected %d words, got %d", test.input, len(test.expected), len(result))
			continue
		}
		for word, count := range test.expected {
			if result[word] != count {
				t.Errorf("WordCount(%q) expected %q to have count %d, got %d", test.input, word, count, result[word])
			}
		}
	}
}

package sandbox

import "testing"

func Dedup(in []int) []int {
	seen := make(map[int]bool)
	result := []int{}

	for _, v := range in {
		if !seen[v] {
			seen[v] = true
			result = append(result, v)
		}
	}

	return result
}

func TestDedup(t *testing.T) {
	tests := []struct {
		name     string
		input    []int
		expected []int
	}{
		{
			name:     "empty slice",
			input:    []int{},
			expected: []int{},
		},
		{
			name:     "no duplicates",
			input:    []int{1, 2, 3, 4, 5},
			expected: []int{1, 2, 3, 4, 5},
		},
		{
			name:     "all duplicates",
			input:    []int{1, 1, 1, 1},
			expected: []int{1},
		},
		{
			name:     "mixed duplicates",
			input:    []int{1, 2, 1, 3, 2, 4},
			expected: []int{1, 2, 3, 4},
		},
		{
			name:     "negative numbers",
			input:    []int{-1, -2, -1, 0, -2},
			expected: []int{-1, -2, 0},
		},
		{
			name:     "single element",
			input:    []int{42},
			expected: []int{42},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := Dedup(tt.input)
			if len(result) != len(tt.expected) {
				t.Errorf("Dedup(%v) = %v, want %v", tt.input, result, tt.expected)
				return
			}
			for i, v := range result {
				if v != tt.expected[i] {
					t.Errorf("Dedup(%v) = %v, want %v", tt.input, result, tt.expected)
					break
				}
			}
		})
	}
}

package sandbox

import (
	"testing"
)

func IsPalindrome(s string) bool {
	left := 0
	right := len(s) - 1

	for left < right {
		// Skip non-alphanumeric characters from the left
		for left < right && !isAlphaNumeric(s[left]) {
			left++
		}

		// Skip non-alphanumeric characters from the right
		for left < right && !isAlphaNumeric(s[right]) {
			right--
		}

		// Compare characters (case-insensitive)
		if toLower(s[left]) != toLower(s[right]) {
			return false
		}

		left++
		right--
	}

	return true
}

func isAlphaNumeric(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
}

func toLower(c byte) byte {
	if c >= 'A' && c <= 'Z' {
		return c + 'a' - 'A'
	}
	return c
}

func TestIsPalindrome(t *testing.T) {
	tests := []struct {
		input    string
		expected bool
	}{
		{"A man a plan a canal Panama", true},
		{"race a car", false},
		{"", true},
		{"a", true},
		{"Madam", true},
		{"No 'x' in Nixon", true},
		{"Mr. Owl ate my metal worm", true},
		{"hello", false},
		{"A1B2b1a", true},
		{"12321", true},
		{"12345", false},
		{"A Santa at NASA", true},
		{"Was it a car or a cat I saw?", true},
		{"tab a cat", false},
		{"Mr. Owl ate my metal worm", true},
	}

	for _, test := range tests {
		result := IsPalindrome(test.input)
		if result != test.expected {
			t.Errorf("IsPalindrome(%q) = %v, want %v", test.input, result, test.expected)
		}
	}
}

package sandbox

import (
	"testing"
)

func Map[T, U any](s []T, f func(T) U) []U {
	result := make([]U, len(s))
	for i, v := range s {
		result[i] = f(v)
	}
	return result
}

func TestMap(t *testing.T) {
	// Test with integers
	numbers := []int{1, 2, 3, 4, 5}
	squared := Map(numbers, func(x int) int { return x * x })
	expected := []int{1, 4, 9, 16, 25}
	for i, v := range squared {
		if v != expected[i] {
			t.Errorf("Map[int]int failed: expected %v, got %v", expected[i], v)
		}
	}

	// Test with strings
	words := []string{"hello", "world", "go"}
	lengths := Map(words, func(s string) int { return len(s) })
	expectedLengths := []int{5, 5, 2}
	for i, v := range lengths {
		if v != expectedLengths[i] {
			t.Errorf("Map[string]int failed: expected %v, got %v", expectedLengths[i], v)
		}
	}

	// Test with empty slice
	empty := []int{}
	result := Map(empty, func(x int) int { return x * 2 })
	if len(result) != 0 {
		t.Errorf("Map with empty slice failed: expected length 0, got %v", len(result))
	}

	// Test with different types
	floats := []float64{1.5, 2.7, 3.14}
	integers := Map(floats, func(f float64) int { return int(f) })
	expectedInts := []int{1, 2, 3}
	for i, v := range integers {
		if v != expectedInts[i] {
			t.Errorf("Map[float64]int failed: expected %v, got %v", expectedInts[i], v)
		}
	}
}

package sandbox

import (
	"errors"
	"strconv"
)

var ErrBadPort = errors.New("bad port")

func ParsePort(s string) (int, error) {
	port, err := strconv.Atoi(s)
	if err != nil {
		return 0, errors.Wrap(ErrBadPort, err)
	}
	if port < 1 || port > 65535 {
		return 0, ErrBadPort
	}
	return port, nil
}

package sandbox

import (
	"sync"
	"testing"
)

type Counter struct {
	mu    sync.Mutex
	count map[string]int
}

func (c *Counter) Inc(key string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.count[key]++
}

func (c *Counter) Get(key string) int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.count[key]
}

func TestCounter(t *testing.T) {
	counter := &Counter{
		count: make(map[string]int),
	}

	// Test basic increment and get
	counter.Inc("test")
	if counter.Get("test") != 1 {
		t.Errorf("Expected 1, got %d", counter.Get("test"))
	}

	counter.Inc("test")
	if counter.Get("test") != 2 {
		t.Errorf("Expected 2, got %d", counter.Get("test"))
	}

	// Test multiple keys
	counter.Inc("key1")
	counter.Inc("key2")
	counter.Inc("key2")
	if counter.Get("key1") != 1 {
		t.Errorf("Expected 1, got %d", counter.Get("key1"))
	}
	if counter.Get("key2") != 2 {
		t.Errorf("Expected 2, got %d", counter.Get("key2"))
	}

	// Test zero value for non-existent key
	if counter.Get("nonexistent") != 0 {
		t.Errorf("Expected 0, got %d", counter.Get("nonexistent"))
	}
}

package sandbox

import (
	"encoding/json"
	"testing"
)

type Point struct {
	X int `json:"x"`
	Y int `json:"y"`
}

func Encode(p Point) (string, error) {
	return json.Marshal(p)
}

func TestEncode(t *testing.T) {
	tests := []struct {
		name string
		p    Point
		want string
	}{
		{
			name: "zero point",
			p:    Point{X: 0, Y: 0},
			want: `{"x":0,"y":0}`,
		},
		{
			name: "positive coordinates",
			p:    Point{X: 1, Y: 2},
			want: `{"x":1,"y":2}`,
		},
		{
			name: "negative coordinates",
			p:    Point{X: -1, Y: -2},
			want: `{"x":-1,"y":-2}`,
		},
		{
			name: "mixed coordinates",
			p:    Point{X: 5, Y: -3},
			want: `{"x":5,"y":-3}`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := Encode(tt.p)
			if err != nil {
				t.Errorf("Encode() error = %v", err)
				return
			}
			if got != tt.want {
				t.Errorf("Encode() = %v, want %v", got, tt.want)
			}
		})
	}
}

package sandbox

import (
	"sort"
	"testing"
)

func SortByLen(ss []string) {
	sort.SliceStable(ss, func(i, j int) bool {
		return len(ss[i]) < len(ss[j])
	})
}

func TestSortByLen(t *testing.T) {
	tests := []struct {
		name     string
		input    []string
		expected []string
	}{
		{
			name:     "empty slice",
			input:    []string{},
			expected: []string{},
		},
		{
			name:     "single element",
			input:    []string{"hello"},
			expected: []string{"hello"},
		},
		{
			name:     "already sorted",
			input:    []string{"a", "bb", "ccc"},
			expected: []string{"a", "bb", "ccc"},
		},
		{
			name:     "reverse sorted",
			input:    []string{"ccc", "bb", "a"},
			expected: []string{"a", "bb", "ccc"},
		},
		{
			name:     "mixed lengths",
			input:    []string{"hello", "hi", "world", "go", "programming"},
			expected: []string{"go", "hi", "hello", "world", "programming"},
		},
		{
			name:     "equal lengths",
			input:    []string{"cat", "dog", "bat", "elephant"},
			expected: []string{"cat", "dog", "bat", "elephant"},
		},
		{
			name:     "with empty strings",
			input:    []string{"", "a", "", "bb"},
			expected: []string{"", "", "a", "bb"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			input := make([]string, len(tt.input))
			copy(input, tt.input)

			SortByLen(input)

			if len(input) != len(tt.expected) {
				t.Errorf("expected length %d, got %d", len(tt.expected), len(input))
				return
			}

			for i, expected := range tt.expected {
				if input[i] != expected {
					t.Errorf("input[%d] = %q, want %q", i, input[i], expected)
				}
			}
		})
	}
}

package sandbox

import (
	"reflect"
	"testing"
)

func Chunk[T any](s []T, n int) [][]T {
	if n < 1 {
		n = 1
	}

	if len(s) == 0 {
		return [][]T{}
	}

	chunks := make([][]T, 0)

	for i := 0; i < len(s); i += n {
		end := i + n
		if end > len(s) {
			end = len(s)
		}
		chunks = append(chunks, s[i:end])
	}

	return chunks
}

func TestChunk(t *testing.T) {
	tests := []struct {
		name string
		s    []int
		n    int
		want [][]int
	}{
		{
			name: "empty slice",
			s:    []int{},
			n:    2,
			want: [][]int{},
		},
		{
			name: "slice smaller than chunk size",
			s:    []int{1, 2, 3},
			n:    5,
			want: [][]int{{1, 2, 3}},
		},
		{
			name: "exact multiple chunks",
			s:    []int{1, 2, 3, 4, 5, 6},
			n:    2,
			want: [][]int{{1, 2}, {3, 4}, {5, 6}},
		},
		{
			name: "remainder chunks",
			s:    []int{1, 2, 3, 4, 5},
			n:    2,
			want: [][]int{{1, 2}, {3, 4}, {5}},
		},
		{
			name: "chunk size of 1",
			s:    []int{1, 2, 3},
			n:    1,
			want: [][]int{{1}, {2}, {3}},
		},
		{
			name: "chunk size larger than slice",
			s:    []int{1, 2},
			n:    5,
			want: [][]int{{1, 2}},
		},
		{
			name: "zero chunk size",
			s:    []int{1, 2, 3},
			n:    0,
			want: [][]int{{1, 2, 3}},
		},
		{
			name: "negative chunk size",
			s:    []int{1, 2, 3},
			n:    -1,
			want: [][]int{{1, 2, 3}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Chunk(tt.s, tt.n)
			if !reflect.DeepEqual(got, tt.want) {
				t.Errorf("Chunk() = %v, want %v", got, tt.want)
			}
		})
	}
}

package sandbox

import (
	"testing"
)

func Max[T int | int64 | float64](xs ...T) (T, bool) {
	if len(xs) == 0 {
		var zero T
		return zero, false
	}

	max := xs[0]
	for _, x := range xs[1:] {
		if x > max {
			max = x
		}
	}

	return max, true
}

func TestMax(t *testing.T) {
	// Test empty slice
	result, ok := Max[int]()
	if ok {
		t.Errorf("Expected false for empty slice, got true")
	}
	if result != 0 {
		t.Errorf("Expected zero value for empty slice, got %v", result)
	}

	// Test single element
	result, ok = Max[int](5)
	if !ok {
		t.Errorf("Expected true for single element, got false")
	}
	if result != 5 {
		t.Errorf("Expected 5, got %v", result)
	}

	// Test multiple integers
	result, ok = Max[int](1, 3, 2, 5, 4)
	if !ok {
		t.Errorf("Expected true for multiple elements, got false")
	}
	if result != 5 {
		t.Errorf("Expected 5, got %v", result)
	}

	// Test multiple int64
	result64, ok := Max[int64](100, 200, 50, 300)
	if !ok {
		t.Errorf("Expected true for multiple int64 elements, got false")
	}
	if result64 != 300 {
		t.Errorf("Expected 300, got %v", result64)
	}

	// Test multiple float64
	resultF64, ok := Max[float64](1.5, 2.7, 1.2, 3.8)
	if !ok {
		t.Errorf("Expected true for multiple float64 elements, got false")
	}
	if resultF64 != 3.8 {
		t.Errorf("Expected 3.8, got %v", resultF64)
	}

	// Test negative numbers
	result, ok = Max[int](-1, -5, -2, -3)
	if !ok {
		t.Errorf("Expected true for negative numbers, got false")
	}
	if result != -1 {
		t.Errorf("Expected -1, got %v", result)
	}

	// Test float64 with negative numbers
	resultF64, ok = Max[float64](-1.5, -2.7, -1.2)
	if !ok {
		t.Errorf("Expected true for negative float64 numbers, got false")
	}
	if resultF64 != -1.2 {
		t.Errorf("Expected -1.2, got %v", resultF64)
	}
}

