package sandbox

import "testing"

func GroupParity(xs []int) map[string][]int {
	result := make(map[string][]int)
	result["even"] = []int{}
	result["odd"] = []int{}

	for _, x := range xs {
		if x%2 == 0 {
			result["even"] = append(result["even"], x)
		} else {
			result["odd"] = append(result["odd"], x)
		}
	}

	return result
}

func TestGroupParity(t *testing.T) {
	tests := []struct {
		name     string
		input    []int
		expected map[string][]int
	}{
		{
			name:  "empty slice",
			input: []int{},
			expected: map[string][]int{
				"even": []int{},
				"odd":  []int{},
			},
		},
		{
			name:  "all even numbers",
			input: []int{2, 4, 6, 8},
			expected: map[string][]int{
				"even": []int{2, 4, 6, 8},
				"odd":  []int{},
			},
		},
		{
			name:  "all odd numbers",
			input: []int{1, 3, 5, 7},
			expected: map[string][]int{
				"even": []int{},
				"odd":  []int{1, 3, 5, 7},
			},
		},
		{
			name:  "mixed numbers",
			input: []int{1, 2, 3, 4, 5, 6},
			expected: map[string][]int{
				"even": []int{2, 4, 6},
				"odd":  []int{1, 3, 5},
			},
		},
		{
			name:  "negative numbers",
			input: []int{-1, -2, -3, -4},
			expected: map[string][]int{
				"even": []int{-2, -4},
				"odd":  []int{-1, -3},
			},
		},
		{
			name:  "zero included",
			input: []int{0, 1, 2, 3},
			expected: map[string][]int{
				"even": []int{0, 2},
				"odd":  []int{1, 3},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := GroupParity(tt.input)
			if len(result["even"]) != len(tt.expected["even"]) {
				t.Errorf("expected even slice length %d, got %d", len(tt.expected["even"]), len(result["even"]))
			}
			for i, v := range result["even"] {
				if v != tt.expected["even"][i] {
					t.Errorf("expected even[%d] = %d, got %d", i, tt.expected["even"][i], v)
				}
			}
			if len(result["odd"]) != len(tt.expected["odd"]) {
				t.Errorf("expected odd slice length %d, got %d", len(tt.expected["odd"]), len(result["odd"]))
			}
			for i, v := range result["odd"] {
				if v != tt.expected["odd"][i] {
					t.Errorf("expected odd[%d] = %d, got %d", i, tt.expected["odd"][i], v)
				}
			}
		})
	}
}

package sandbox

import (
	"testing"
)

func Flatten[T any](in [][]T) []T {
	if len(in) == 0 {
		return []T{}
	}

	totalLen := 0
	for _, slice := range in {
		totalLen += len(slice)
	}

	result := make([]T, 0, totalLen)
	for _, slice := range in {
		result = append(result, slice...)
	}

	return result
}

func TestFlatten(t *testing.T) {
	// Test empty input
	result := Flatten[int]([][]int{})
	if len(result) != 0 {
		t.Errorf("Expected empty slice, got %v", result)
	}

	// Test single empty sub-slice
	result = Flatten[int]([][]int{{}})
	if len(result) != 0 {
		t.Errorf("Expected empty slice, got %v", result)
