)

// SumDigits sums the decimal digits in s, returning an error wrapping strconv via fmt.Errorf %w on a non-digit
func SumDigits(s string) (int, error) {
	sum := 0
	for _, r := range s {
		if !strings.ContainsRune("0123456789", r) {
			return 0, fmt.Errorf("invalid digit %c: %w", r, strconv.ErrSyntax)
		}
		digit := int(r - '0')
		sum += digit
	}
	return sum, nil
}

