func Balanced(s string) bool {
	stack := []rune{}
	pairs := map[rune]rune{
		')': '(',
		']': '[',
		'}': '{',
	}

	for _, char := range s {
		switch char {
		case '(', '[', '{':
			stack = append(stack, char)
		case ')', ']', '}':
			if len(stack) == 0 {
				return false
			}
			last := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			if last != pairs[char] {
				return false
			}
		}
	}

	return len(stack) == 0
}

func TestBalanced(t *testing.T) {
	tests := []struct {
		input    string
		expected bool
	}{
		{"()", true},
		{"()[]{}", true},
		{"([{}])", true},
		{"([)]", false},
		{"(((", false},
		{")))", false},
		{"({[}])", false},
		{"", true},
		{"abc(def)ghi", true},
		{"abc(def(ghi)jkl)mno", true},
		{"abc(def(ghi)jkl)mno)", false},
		{"{[}]", false},
		{"a(b[c{d}e]f)g", true},
	}

	for _, test := range tests {
		result := Balanced(test.input)
		if result != test.expected {
			t.Errorf("Balanced(%q) = %v, want %v", test.input, result, test.expected)
