	"strings"
)

func Decode(s string) string {
	var result strings.Builder
	i := 0

	for i < len(s) {
		// Get the character
		char := s[i]
		i++

		// Extract the number
		numStr := ""
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			numStr += string(s[i])
			i++
		}

		// Convert number and repeat character
		count, _ := strconv.Atoi(numStr)
		for j := 0; j < count; j++ {
			result.WriteByte(char)
		}
	}

	return result.String()
}

