func Caesar(s string, n int) string {
	result := make([]rune, len(s))

	for i, r := range s {
		if r >= 'a' && r <= 'z' {
			// Handle lowercase letters
			shifted := (int(r-'a') + n) % 26
			if shifted < 0 {
				shifted += 26
			}
			result[i] = rune(shifted + 'a')
		} else if r >= 'A' && r <= 'Z' {
			// Handle uppercase letters
			shifted := (int(r-'A') + n) % 26
			if shifted < 0 {
				shifted += 26
			}
			result[i] = rune(shifted + 'A')
		} else {
			// Leave non-letters unchanged
			result[i] = r
		}
	}

	return string(result)
}

