import (
	"sort"
	"strings"
)

func TopK(s string, k int) []string {
	if s == "" || k <= 0 {
		return []string{}
	}

	// Count frequency of each word
	wordCount := make(map[string]int)
	words := strings.Fields(s)
	for _, word := range words {
		wordCount[word]++
	}

	// Create slice of unique words
	uniqueWords := make([]string, 0, len(wordCount))
	for word := range wordCount {
		uniqueWords = append(uniqueWords, word)
	}

	// Sort by frequency (descending) and then alphabetically (ascending)
	sort.Slice(uniqueWords, func(i, j int) bool {
		countI := wordCount[uniqueWords[i]]
		countJ := wordCount[uniqueWords[j]]
		if countI != countJ {
			return countI > countJ // Higher frequency first
		}
		return uniqueWords[i] < uniqueWords[j] // Alphabetical order
	})

	// Return top k words
	if k > len(uniqueWords) {
		k = len(uniqueWords)
	}
	return uniqueWords[:k]
}

