// NotFoundError represents a not found error with a code
type NotFoundError struct {
	Code int
}

// Error returns the error message for NotFoundError
func (e *NotFoundError) Error() string {
	return fmt.Sprintf("not found (code: %d)", e.Code)
}

// CodeOf returns the Code from a NotFoundError anywhere in the error chain
// or -1 if not found
func CodeOf(err error) int {
	var notFoundErr *NotFoundError
	if errors.As(err, &notFoundErr) {
		return notFoundErr.Code
	}
	return -1
}

