func ParseQuery(q string) map[string][]string {
	result := make(map[string][]string)

	if q == "" {
		return result
	}

	pairs := strings.Split(q, "&")
	for _, pair := range pairs {
		if pair == "" {
			continue
		}

		idx := strings.Index(pair, "=")
		if idx == -1 {
			continue
		}

		key := pair[:idx]
		value := pair[idx+1:]

		if key == "" {
			continue
		}

		result[key] = append(result[key], value)
	}

	return result
}

func TestParseQuery(t *testing.T) {
	tests := []struct {
		name string
		q    string
		want map[string][]string
	}{
		{
			name: "basic query",
			q:    "a=1&b=2&a=3",
			want: map[string][]string{"a": {"1", "3"}, "b": {"2"}},
		},
		{
			name: "empty string",
			q:    "",
			want: map[string][]string{},
		},
		{
			name: "empty pairs",
			q:    "&a=1&&b=2&",
			want: map[string][]string{"a": {"1"}, "b": {"2"}},
		},
		{
			name: "no equals sign",
			q:    "a&b=1&c",
			want: map[string][]string{"b": {"1"}},
		},
		{
			name: "empty key",
			q:    "=value&a=1",
			want: map[string][]string{"a": {"1"}},
		},
		{
			name: "multiple values",
			q:    "a=1&a=2&a=3",
			want: map[string][]string{"a": {"1", "2", "3"}},
		},
		{
			name: "single pair",
			q:    "key=value",
			want: map[string][]string{"key": {"value"}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := ParseQuery(tt.q)
			if len(got) != len(tt.want) {
				t.Errorf("ParseQuery() got %v pairs, want %v", len(got), len(tt.want))
				return
			}

			for key, wantValues := range tt.want {
				gotValues, exists := got[key]
				if !exists {
					t.Errorf("ParseQuery() missing key %s", key)
					continue
				}

				if len(gotValues) != len(wantValues) {
					t.Errorf("ParseQuery() key %s got %v values, want %v", key, len(gotValues), len(wantValues))
					continue
				}

				for i, wantValue := range wantValues {
					if gotValues[i] != wantValue {
						t.Errorf("ParseQuery() key %s[%d] got %s, want %s", key, i, gotValues[i], wantValue)
					}
				}
			}
		})
	}
}

