import (
	"sync"
)

func ParallelSum(nums []int, workers int) int {
	jobs := make(chan int, len(nums))
	for _, num := range nums {
		jobs <- num
	}
	close(jobs)

	var wg sync.WaitGroup
	result := make(chan int, workers)

	wg.Add(workers)
	for i := 0; i < workers; i++ {
		go func() {
			defer wg.Done()
			sum := 0
			for num := range jobs {
				sum += num
			}
			result <- sum
		}()
	}

	go func() {
		wg.Wait()
		close(result)
	}()

	total := 0
	for sum := range result {
		total += sum
	}

	return total
}

