	if len(longStrings) != len(expectedLong) {
		t.Errorf("Expected %d elements, got %d", len(expectedLong), len(longStrings))
	}
	for i, v := range expectedLong {
		if longStrings[i] != v {
			t.Errorf("Expected %s at index %d, got %s", v, i, longStrings[i])
		}
	}

	// Test with empty slice
	empty := Filter([]int{}, func(n int) bool { return n > 0 })
	if len(empty) != 0 {
		t.Errorf("Expected empty slice, got %v", empty)
	}

	// Test with all elements filtered out
	allFiltered := Filter([]int{1, 2, 3}, func(n int) bool { return n > 10 })
	if len(allFiltered) != 0 {
		t.Errorf("Expected empty slice, got %v", allFiltered)
	}

	// Test with all elements kept
	allKept := Filter([]string{"a", "b", "c"}, func(s string) bool { return len(s) > 0 })
	expectedAll := []string{"a", "b", "c"}
	if len(allKept) != len(expectedAll) {
		t.Errorf("Expected %d elements, got %d", len(expectedAll), len(allKept))
	}
	for i, v := range expectedAll {
		if allKept[i] != v {
			t.Errorf("Expected %s at index %d, got %s", v, i, allKept[i])
		}
	}
}

