package sandbox

import (
	"context"
	"testing"
)

func TestCountUntil(t *testing.T) {
	t.Run("context cancellation", func(t *testing.T) {
		ctx, cancel := context.WithCancel(context.Background())
		ch := make(chan int)

		go func() {
			ch <- 1
			ch <- 2
			cancel()
		}()

		result := CountUntil(ctx, ch)
		if result != 2 {
			t.Errorf("Expected 2, got %d", result)
		}
	})

	t.Run("channel closure", func(t *testing.T) {
		ctx := context.Background()
		ch := make(chan int)

		go func() {
			ch <- 1
			ch <- 2
			close(ch)
		}()

		result := CountUntil(ctx, ch)
		if result != 2 {
			t.Errorf("Expected 2, got %d", result)
		}
	})

	t.Run("empty channel", func(t *testing.T) {
		ctx := context.Background()
		ch := make(chan int)

		go func() {
			close(ch)
		}()

		result := CountUntil(ctx, ch)
		if result != 0 {
			t.Errorf("Expected 0, got %d", result)
		}
	})

	t.Run("context already cancelled", func(t *testing.T) {
		ctx, cancel := context.WithCancel(context.Background())
		cancel()
		ch := make(chan int)

		result := CountUntil(ctx, ch)
		if result != 0 {
			t.Errorf("Expected 0, got %d", result)
		}
	})

	t.Run("multiple values before cancellation", func(t *testing.T) {
		ctx, cancel := context.WithCancel(context.Background())
		ch := make(chan int)

		go func() {
			ch <- 1
			ch <- 2
			ch <- 3
			ch <- 4
			cancel()
		}()

		result := CountUntil(ctx, ch)
		if result != 4 {
			t.Errorf("Expected 4, got %d", result)
		}
	})
}

package sandbox

import (
	"bytes"
	"io"
	"strings"
	"testing"
)

func ReadChunks(r io.Reader, size int) ([][]byte, error) {
	var chunks [][]byte
	buffer := make([]byte, size)

	for {
		n, err := r.Read(buffer)
		if n > 0 {
			chunks = append(chunks, append([]byte(nil), buffer[:n]...))
		}
		if err != nil {
			if err == io.EOF {
				break
			}
			return nil, err
		}
	}

	return chunks, nil
}

func TestReadChunks(t *testing.T) {
	tests := []struct {
		name    string
		reader  io.Reader
		size    int
		want    [][]byte
		wantErr bool
	}{
		{
			name:    "empty reader",
			reader:  strings.NewReader(""),
			size:    10,
			want:    [][]byte{},
			wantErr: false,
		},
		{
			name:    "single chunk",
			reader:  strings.NewReader("hello"),
			size:    10,
			want:    [][]byte{[]byte("hello")},
			wantErr: false,
		},
		{
			name:    "multiple exact chunks",
			reader:  strings.NewReader("hello world test"),
			size:    5,
			want:    [][]byte{[]byte("hello"), []byte(" worl"), []byte("d te"), []byte("st")},
			wantErr: false,
		},
		{
			name:    "partial last chunk",
			reader:  strings.NewReader("hello world test"),
			size:    7,
			want:    [][]byte{[]byte("hello w"), []byte("orld te"), []byte("st")},
			wantErr: false,
		},
		{
			name:    "size larger than content",
			reader:  strings.NewReader("short"),
			size:    100,
			want:    [][]byte{[]byte("short")},
			wantErr: false,
		},
		{
			name:    "zero size",
			reader:  strings.NewReader("test"),
			size:    0,
			want:    [][]byte{},
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := ReadChunks(tt.reader, tt.size)
			if (err != nil) != tt.wantErr {
				t.Errorf("ReadChunks() error = %v, wantErr %v", err, tt.wantErr)
				return
			}
			if !bytes.EqualFold(bytes.Join(got, []byte{}), bytes.Join(tt.want, []byte{})) {
				t.Errorf("ReadChunks() = %v, want %v", got, tt.want)
			}
		})
	}
}

package sandbox

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

// Chain creates a new http.Handler by applying middlewares to the given handler.
// The first middleware in the list is the outermost middleware.
func Chain(h http.Handler, mws ...func(http.Handler) http.Handler) http.Handler {
	if len(mws) == 0 {
		return h
	}

	// Start with the innermost handler
	result := h

	// Apply middlewares from right to left (outermost first)
	for i := len(mws) - 1; i >= 0; i-- {
		result = mws[i](result)
	}

	return result
}

func TestChain(t *testing.T) {
	// Create a test handler that records if it was called
	var called []string
	testHandler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		called = append(called, "handler")
		w.WriteHeader(http.StatusOK)
	})

	// Create middleware that records when it's called
	middleware1 := func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			called = append(called, "middleware1")
			next.ServeHTTP(w, r)
		})
	}

	middleware2 := func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			called = append(called, "middleware2")
			next.ServeHTTP(w, r)
		})
	}

	// Chain the middleware with the handler
	chained := Chain(testHandler, middleware1, middleware2)

	// Create a test request
	req := httptest.NewRequest("GET", "/", nil)
	rec := httptest.NewRecorder()

	// Execute the chained handler
	chained.ServeHTTP(rec, req)

	// Verify the order of execution (outermost first)
	expected := []string{"middleware1", "middleware2", "handler"}
	if len(called) != len(expected) {
		t.Errorf("Expected %d calls, got %d", len(expected), len(called))
	}

	for i, exp := range expected {
		if called[i] != exp {
			t.Errorf("Expected call %d to be %s, got %s", i, exp, called[i])
		}
	}

	// Verify response status
	if rec.Code != http.StatusOK {
		t.Errorf("Expected status %d, got %d", http.StatusOK, rec.Code)
	}

	// Test with no middlewares
	chainedNoMw := Chain(testHandler)
	req2 := httptest.NewRequest("GET", "/", nil)
	rec2 := httptest.NewRecorder()
	chainedNoMw.ServeHTTP(rec2, req2)
	if rec2.Code != http.StatusOK {
		t.Errorf("Expected status %d, got %d", http.StatusOK, rec2.Code)
	}

	// Test with empty middleware slice
	chainedEmpty := Chain(testHandler)
	req3 := httptest.NewRequest("GET", "/", nil)
	rec3 := httptest.NewRecorder()
	chainedEmpty.ServeHTTP(rec3, req3)
	if rec3.Code != http.StatusOK {
		t.Errorf("Expected status %d, got %d", http.StatusOK, rec3.Code)
	}
}
